        foreach ($translations as $item) {
            $key = $item['key'];
            // Determine group from key prefix (e.g. 'nav.dashboard' → 'nav')
            $group = explode('.', $key)[0];

            foreach (['en', 'ar'] as $locale) {
                Translation::updateOrCreate(
                    ['locale' => $locale, 'key' => $key],
                    [
                        'value'      => $item[$locale],
                        'group'      => $group,
                        'updated_at' => now(),
                    ]
                );
            }
        }
